40	/**
41	 * Manages the discovery, loading, validation, and registration of
42	 * AgentDefinitions.
43	 */
44	export class AgentRegistry {
45	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
46	  private readonly agents = new Map<string, AgentDefinition<any>>();
47	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
48	  private readonly allDefinitions = new Map<string, AgentDefinition<any>>();
49	
50	  constructor(private readonly config: Config) {}
51	
52	  /**
53	   * Discovers and loads agents.
54	   */
55	  async initialize(): Promise<void> {
56	    coreEvents.on(CoreEvent.ModelChanged, this.onModelChanged);
57	
58	    await this.loadAgents();
59	  }
60	
61	  private onModelChanged = () => {
62	    this.refreshAgents('local').catch((e) => {
63	      debugLogger.error(
64	        '[AgentRegistry] Failed to refresh agents on model change:',
65	        e,
66	      );
67	    });
68	  };
69	
70	  /**
71	   * Clears the current registry and re-scans for agents.
72	   */
73	  async reload(): Promise<void> {
74	    this.config.getA2AClientManager()?.clearCache();
75	    await this.config.reloadAgents();
76	    this.agents.clear();
77	    this.allDefinitions.clear();
78	    await this.loadAgents();
79	    coreEvents.emitAgentsRefreshed();
80	  }
81	
82	  /**
83	   * Acknowledges and registers a previously unacknowledged agent.
84	   */
85	  async acknowledgeAgent(agent: AgentDefinition): Promise<void> {
86	    const ackService = this.config.getAcknowledgedAgentsService();
87	    const projectRoot = this.config.getProjectRoot();
88	    if (agent.metadata?.hash) {
89	      await ackService.acknowledge(
90	        projectRoot,
91	        agent.name,
92	        agent.metadata.hash,
93	      );
94	      await this.registerAgent(agent);
95	      coreEvents.emitAgentsRefreshed();
96	    }
97	  }
98	
99	  /**
100	   * Disposes of resources and removes event listeners.
101	   */
102	  dispose(): void {
103	    coreEvents.off(CoreEvent.ModelChanged, this.onModelChanged);
104	  }
105	
106	  private async loadAgents(): Promise<void> {
107	    this.agents.clear();
108	    this.allDefinitions.clear();
109	    this.loadBuiltInAgents();
110	
111	    if (!this.config.isAgentsEnabled()) {
112	      return;
113	    }
114	
115	    // Load user-level agents: ~/.gemini/agents/
116	    const userAgentsDir = Storage.getUserAgentsDir();
117	    const userAgents = await loadAgentsFromDirectory(userAgentsDir);
118	    for (const error of userAgents.errors) {
119	      debugLogger.warn(
120	        `[AgentRegistry] Error loading user agent: ${error.message}`,
121	      );
122	      coreEvents.emitFeedback('error', `Agent loading error: ${error.message}`);
123	    }
124	    await Promise.allSettled(
125	      userAgents.agents.map(async (agent) => {
126	        try {
127	          await this.registerAgent(agent);
128	        } catch (e) {
129	          debugLogger.warn(
130	            `[AgentRegistry] Error registering user agent "${agent.name}":`,
131	            e,
132	          );
133	          coreEvents.emitFeedback(
134	            'error',
135	            `Error registering user agent "${agent.name}": ${e instanceof Error ? e.message : String(e)}`,
136	          );
137	        }
138	      }),
139	    );
140	
141	    // Load project-level agents: .gemini/agents/ (relative to Project Root)
142	    const folderTrustEnabled = this.config.getFolderTrust();
143	    const isTrustedFolder = this.config.isTrustedFolder();
144	
145	    if (!folderTrustEnabled || isTrustedFolder) {
146	      const projectAgentsDir = this.config.storage.getProjectAgentsDir();
147	      const projectAgents = await loadAgentsFromDirectory(projectAgentsDir);
148	      for (const error of projectAgents.errors) {
149	        coreEvents.emitFeedback(
150	          'error',
151	          `Agent loading error: ${error.message}`,
152	        );
153	      }
154	
155	      const ackService = this.config.getAcknowledgedAgentsService();
156	      const projectRoot = this.config.getProjectRoot();
157	      const unacknowledgedAgents: AgentDefinition[] = [];
158	      const agentsToRegister: AgentDefinition[] = [];
159	
160	      for (const agent of projectAgents.agents) {
161	        // If it's a remote agent, use the agentCardUrl as the hash.
162	        // This allows multiple remote agents in a single file to be tracked independently.
163	        if (agent.kind === 'remote') {
164	          if (!agent.metadata) {
165	            agent.metadata = {};
166	          }
167	          agent.metadata.hash =
168	            agent.agentCardUrl ??
169	            (agent.agentCardJson
170	              ? crypto
171	                  .createHash('sha256')
172	                  .update(agent.agentCardJson)
173	                  .digest('hex')
174	              : undefined);
175	        }
176	
177	        if (!agent.metadata?.hash) {
178	          agentsToRegister.push(agent);
179	          continue;
180	        }
181	
182	        const isAcknowledged = await ackService.isAcknowledged(
183	          projectRoot,
184	          agent.name,
185	          agent.metadata.hash,
186	        );
187	
188	        if (isAcknowledged) {
189	          agentsToRegister.push(agent);
190	        } else {
191	          unacknowledgedAgents.push(agent);
192	        }
193	      }
194	
195	      if (unacknowledgedAgents.length > 0) {
196	        coreEvents.emitAgentsDiscovered(unacknowledgedAgents);
197	      }
198	
199	      await Promise.allSettled(
200	        agentsToRegister.map(async (agent) => {
201	          try {
202	            await this.registerAgent(agent);
203	          } catch (e) {
204	            debugLogger.warn(
205	              `[AgentRegistry] Error registering project agent "${agent.name}":`,
206	              e,
207	            );
208	            coreEvents.emitFeedback(
209	              'error',
210	              `Error registering project agent "${agent.name}": ${e instanceof Error ? e.message : String(e)}`,
211	            );
212	          }
213	        }),
214	      );
215	    } else {
216	      coreEvents.emitFeedback(
217	        'info',
218	        'Skipping project agents due to untrusted folder. To enable, ensure that the project root is trusted.',
219	      );
220	    }
221	
