112	export class BrowserManager {
113	  // --- Static singleton management ---
114	  private static instances = new Map<string, BrowserManager>();
115	
116	  /**
117	   * Returns the cache key for a given config.
118	   * Uses `sessionMode:profilePath` so different profiles get separate instances.
119	   */
120	  private static getInstanceKey(config: Config): string {
121	    const browserConfig = config.getBrowserAgentConfig();
122	    const sessionMode = browserConfig.customConfig.sessionMode ?? 'persistent';
123	    const profilePath = browserConfig.customConfig.profilePath ?? 'default';
124	    return `${sessionMode}:${profilePath}`;
125	  }
126	
127	  /**
128	   * Returns an existing BrowserManager for the current config's session mode
129	   * and profile, or creates a new one.
130	   */
131	  static getInstance(config: Config): BrowserManager {
132	    const key = BrowserManager.getInstanceKey(config);
133	    let instance = BrowserManager.instances.get(key);
134	    if (!instance) {
135	      instance = new BrowserManager(config);
136	      BrowserManager.instances.set(key, instance);
137	      debugLogger.log(`Created new BrowserManager singleton (key: ${key})`);
138	    } else {
139	      debugLogger.log(
140	        `Reusing existing BrowserManager singleton (key: ${key})`,
141	      );
142	    }
143	    return instance;
144	  }
145	
