157	      if (result.status === 'rejected') {
158	        debugLogger.error(
159	          `Error during BrowserManager cleanup: ${result.reason instanceof Error ? result.reason.message : String(result.reason)}`,
160	        );
161	      }
162	    }
163	    BrowserManager.instances.clear();
164	  }
165	
166	  /**
167	   * Alias for resetAll — used by CLI exit cleanup for clarity.
168	   */
169	  static async closeAll(): Promise<void> {
170	    await BrowserManager.resetAll();
171	  }
