/**
 * @fileoverview Helpers for detecting the sandbox the CLI is running inside.
 *
 * The `SANDBOX` environment variable is set by the CLI launcher:
 * - `sandbox-exec`            → macOS Seatbelt (filesystem) sandbox
 * - `sandbox:none`            → sandboxing explicitly disabled
 * - any other non-empty value → a container sandbox (Docker/Podman/etc.)
 * - unset                     → no sandbox
 */

/** The kind of sandbox the process is running in. */
export type SandboxKind = 'container' | 'seatbelt' | 'none';

/**
 * Detects the sandbox kind from the `SANDBOX` environment variable.
 */
export function detectSandboxKind(): SandboxKind {
  const sandbox = process.env['SANDBOX'];
  if (!sandbox || sandbox === 'sandbox:none') {
    return 'none';
  }
  if (sandbox === 'sandbox-exec') {
    return 'seatbelt';
  }
  return 'container';
}

/**
 * Returns true when running inside a container sandbox (Docker/Podman/etc.).
 */
export function isContainerSandbox(): boolean {
  return detectSandboxKind() === 'container';
}

/**
 * Returns true when running inside a macOS Seatbelt filesystem sandbox.
 */
export function isSeatbeltSandbox(): boolean {
  return detectSandboxKind() === 'seatbelt';
}
